INSERT INTO projects (slug,title,client,location,category,summary,body,pv_kwp,inverter_kw,battery_kwh,images,featured,sort) VALUES ('mm2-plaza-benin-city','MM2 Plaza — MM2 Enterprise','MM2 Enterprise','Benin City, Edo','commercial','Grid-tied hybrid solar PV system with integrated battery storage for reliable supply, optimised load management and peak shaving across a busy commercial plaza.','<h2>The challenge</h2><p>A multi-tenant plaza with shops and offices was paying heavily for diesel to cover frequent grid outages, and voltage swings were damaging tenants’ equipment.</p><h2>What we built</h2><p>We designed a hybrid plant that runs the plaza on solar during the day, charges a 107.5 kWh battery bank, and draws on the grid only when needed. The system manages loads automatically and shaves the evening peak.</p><ul><li>62 kWp rooftop PV array on the existing metal roof</li><li>100 kW hybrid inverter capacity</li><li>107.5 kWh battery storage</li><li>Surge protection, earthing and labelled distribution for every tenant circuit</li></ul><h2>The result</h2><p>Stable power for tenants, far fewer generator hours, and a system the facility manager can monitor remotely.</p>',62,100,107.5,'["/images/site/mm2-plaza-rooftop.webp","/images/site/battery-room-lithium.webp"]',1,1);
INSERT INTO projects (slug,title,client,location,category,summary,body,pv_kwp,inverter_kw,battery_kwh,images,featured,sort) VALUES ('qoray-ev-charging-station-ilorin','QORAY Charging Station','QORAY','Ilorin, Kwara','industrial','Hybrid solar PV installation with battery backup that keeps an electric-tricycle charging hub running all day with minimal generator use.','<h2>The challenge</h2><p>An electric keke charging station needs dependable power from early morning to late night. Relying on the grid and diesel made charging unreliable and expensive.</p><h2>What we built</h2><p>A 120.5 kWp solar canopy that doubles as shade for parked vehicles, paired with 90 kW of inverter capacity and 150 kWh of battery storage.</p><ul><li>120.5 kWp solar canopy</li><li>90 kW hybrid inverters</li><li>150 kWh battery storage</li></ul><h2>The result</h2><p>Operational continuity for the fleet, lower energy cost per charge and a visible showcase of clean mobility in Ilorin.</p>',120.5,90,150,'["/images/site/qoray-charging-station.webp","/images/site/inverter-bank.webp"]',1,2);
INSERT INTO projects (slug,title,client,location,category,summary,body,pv_kwp,inverter_kw,battery_kwh,images,featured,sort) VALUES ('mainframes-international-home-of-drinks-benin','Mainframes International — Home of Drinks','Mainframes International','Benin City, Edo','commercial','Grid-connected hybrid solar PV system with integrated storage designed for stable, uninterrupted supply to a busy drinks distribution business.','<h2>The challenge</h2><p>Cold rooms, coolers and point-of-sale systems cannot afford outages. The business needed clean, stable power without the noise and fuel bills of a large generator.</p><h2>What we built</h2><p>A 49.6 kWp hybrid system with 40 kW inverter capacity and 30 kWh of lithium storage, configured to prioritise refrigeration loads.</p><h2>The result</h2><p>Uninterrupted supply for refrigeration and sales, and reduced reliance on diesel.</p>',49.6,40,30,'["/images/site/mainframes-inverters.webp"]',1,3);
INSERT INTO faqs (question,answer,category,sort) VALUES ('How much does a solar system cost in Nigeria?','Our complete installed packages start from about ₦1.16 million for a 1kVA starter system and go up to ₦10.8 million for a 10kVA system with 35 kWh of storage. The final price depends on your appliances, backup hours, battery type and roof. A free load audit gives you an exact written quote.','pricing',1);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Can solar power my air conditioner?','Yes. Inverter ACs are the easiest to run on solar. A 1.5HP inverter AC typically needs at least a 5kVA system with enough panels and storage for the hours you want it on. Tell us how many ACs and for how long, and we will size it properly.','sizing',2);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Lithium or lead-acid batteries — which should I choose?','Lead-acid (tubular) batteries cost less upfront. Lithium-ion (LiFePO4) batteries cost more but last several times longer, can be used more deeply, charge faster and need no topping up. Over the life of the system, lithium usually costs less per year of use.','batteries',3);
INSERT INTO faqs (question,answer,category,sort) VALUES ('How long do solar panels and batteries last?','Quality solar panels typically carry 10–12 year product and 25–30 year performance warranties. Hybrid inverters usually carry 2–5 years. Lithium batteries commonly last 6,000 cycles or more; tubular lead-acid batteries around 1,500 cycles, depending on use and care.','general',4);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Will my system work during the rainy season or harmattan?','Yes. Panels still produce on cloudy days, just less. We size the array with Nigerian weather in mind, and your inverter can also charge from the grid or a generator when there is not enough sun. Wiping harmattan dust off the panels restores lost output.','general',5);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Do you offer installment payments?','Yes. Through our Power-as-a-Product (PaaP) plan you can pay a deposit and spread the balance over monthly payments. Customers who pay in full can qualify for a discount. See the financing page or ask us for terms.','financing',6);
INSERT INTO faqs (question,answer,category,sort) VALUES ('How long does installation take?','Most home systems are installed in one to two days once equipment is on site. Commercial and industrial projects are scheduled after design approval and typically take one to four weeks depending on size.','installation',7);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Which areas do you cover?','We have branches in Lagos (head office, Surulere), Abuja, Port Harcourt, Kano and Benin City, and we install in surrounding states. Contact the nearest branch for a site visit.','general',8);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Can I add more panels or batteries later?','Usually, yes — if the inverter has spare capacity. We design systems with room to grow and will tell you the expansion limits in your quote.','sizing',9);
INSERT INTO faqs (question,answer,category,sort) VALUES ('What maintenance does a solar system need?','Clean the panels every two to four weeks in dusty months, keep the inverter area ventilated, and book a professional check every six months. Lead-acid batteries need water level checks; lithium batteries do not. Our solar care guide explains everything.','maintenance',10);
INSERT INTO faqs (question,answer,category,sort) VALUES ('My inverter is beeping. What should I do?','Note the error code or light on the screen, reduce the load by switching off heavy appliances, and check that the battery and breakers are on. If it continues, open a support ticket or call us — do not open the inverter or battery terminals yourself.','support',11);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Do you sell equipment without installation?','Yes, our online shop sells panels, inverters, batteries and accessories, and we can deliver. We strongly recommend professional installation to protect your warranty and your safety.','shop',12);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Is solar cheaper than running a generator?','For most homes and businesses that run a generator daily, yes. Solar has a higher upfront cost but almost no running cost, while fuel and servicing costs keep rising. Our load calculator compares your current spend with a solar system.','pricing',13);
INSERT INTO faqs (question,answer,category,sort) VALUES ('Do I need permission to install solar on my roof?','For private homes, you generally do not need a permit for rooftop solar. For rented property, get written consent from the landlord. For estates and commercial buildings, we help you work with the facility manager.','installation',14);
