INSERT INTO posts (slug,title,category,cover,published_at,read_minutes,excerpt,seo_description,body,status,author_name,tags,seo_title) VALUES ('how-to-size-a-solar-system-for-your-home-in-nigeria','How to size a solar system for your home in Nigeria','guides','/images/site/battery-room-lithium.webp','2026-09-15 01:02:16',6,'A simple, step-by-step method to work out the inverter, battery and panel sizes your home actually needs — before you talk to any installer.','Step-by-step guide to sizing a home solar system in Nigeria: list your appliances, calculate daily kWh, choose inverter kVA, battery capacity and number of panels.','<p>The most common reason solar systems disappoint is simple: they were sized from a price, not from the home. Before you compare quotes, spend fifteen minutes with this method. You will know roughly what you need and be able to spot an under-sized offer.</p>
INSERT INTO posts (slug,title,category,cover,published_at,read_minutes,excerpt,seo_description,body,status,author_name,tags,seo_title) VALUES ('lithium-vs-lead-acid-tubular-batteries-nigeria','Lithium vs lead-acid (tubular) batteries: which should you choose?','guides','/images/site/inverter-bank.webp','2026-09-24 01:02:16',5,'Tubular batteries are cheaper today. Lithium batteries are often cheaper over the life of your system. Here is how to decide.','Compare lithium (LiFePO4) and tubular lead-acid inverter batteries in Nigeria: cost, lifespan, usable capacity, maintenance and which is best for your home or business.','<p>The battery is the most expensive part of most backup systems, and the one people most often regret choosing. Here is a clear comparison of the two options we install.</p>
INSERT INTO posts (slug,title,category,cover,published_at,read_minutes,excerpt,seo_description,body,status,author_name,tags,seo_title) VALUES ('solar-vs-generator-cost-nigeria','Solar vs generator: how to compare the real cost for your home','finance','/images/site/team-installing-panels.webp','2026-10-03 01:02:16',5,'Fuel, servicing, repairs and noise add up. Use this simple worksheet with your own numbers to see when solar pays for itself.','Compare the cost of running a petrol or diesel generator with a solar and battery system in Nigeria. A simple worksheet to calculate your payback period.','<p>Prices for petrol and diesel change often, so instead of quoting numbers that will be out of date next month, this guide gives you a worksheet. Fill it in with your own receipts.</p>
INSERT INTO posts (slug,title,category,cover,published_at,read_minutes,excerpt,seo_description,body,status,author_name,tags,seo_title) VALUES ('solar-panel-care-harmattan-rainy-season','How to care for your solar panels in harmattan and rainy season','solar-care','/images/site/mm2-plaza-rooftop.webp','2026-10-11 01:02:16',4,'Harmattan dust can cut output noticeably. Here is a safe cleaning routine and what to check before the rains.','Solar panel cleaning and maintenance tips for Nigeria: how to clean dust during harmattan, what to check in the rainy season, and when to call a technician.','<p>Solar panels have no moving parts, but Nigerian weather still asks a little of you. Two seasons matter most.</p>
INSERT INTO posts (slug,title,category,cover,published_at,read_minutes,excerpt,seo_description,body,status,author_name,tags,seo_title) VALUES ('inverter-beeping-error-lights-what-they-mean','Inverter beeping? What the alarms and error lights usually mean','solar-care','/images/site/mainframes-inverters.webp','2026-10-17 01:02:16',4,'Most inverter alarms point to a handful of causes: overload, low battery, high temperature or a grid problem. Here is what to do safely.','Why is my inverter beeping? Common inverter alarms in Nigeria explained — overload, low battery, over-temperature and grid faults — and safe steps to take.','<p>Every inverter brand has its own codes, so always check your manual or the screen message. But most alarms come down to a few causes.</p>
INSERT INTO posts (slug,title,category,cover,published_at,read_minutes,excerpt,seo_description,body,status,author_name,tags,seo_title) VALUES ('case-study-62kwp-hybrid-solar-mm2-plaza-benin','Case study: a 62 kWp hybrid solar plant for MM2 Plaza, Benin City','case-studies','/images/site/mm2-plaza-rooftop.webp','2026-10-22 01:02:16',3,'How we designed a hybrid system with 107.5 kWh of storage to keep a multi-tenant plaza running and shave its evening peak.','Case study: Vertical Solar designed and installed a 62 kWp hybrid solar PV system with 100 kW inverters and 107.5 kWh battery storage at MM2 Plaza, Benin City.','<p>MM2 Plaza is a busy commercial building in Benin City with shops and offices. Frequent outages meant long generator hours, and voltage swings were damaging tenants'' equipment.</p>
INSERT INTO popups (title,body,image,cta_text,cta_url,style,pages,trigger,delay_seconds,frequency,active) VALUES ('Buy now, pay later on a 3.5kVA system','Pay in full and get 5% off any purchase, or spread the cost. Every purchase includes installation and one year of maintenance.','/images/site/promo-buy-now-pay-later.webp','Claim the offer','/get-quote?package=3.5kVA%20promo','corner','/,/packages,/financing','delay',14,'session',1);
